#include <bits/stdc++.h>using namespace std;#define int long long int T, n, a[505][505]; bool ck(int x, int y){    return x >= 1 && y >= 1 && x <= n && y <= n;} void O_o(){    cin >> n;    memset(a, -1, sizeof(a));     int x, y;    if(n & 1) x = y = n / 2 + 1;    else x = y = n / 2;     int cnt = 0;    a[x][y] = cnt++;     // 右 下 左 上    int dx[4] = {0, 1, 0, -1};    int dy[4] = {1, 0, -1, 0};    int step = 1;     while(cnt < n * n){        for(int d = 0;d < 4;d++){            for(int t = 0;t < step;t++){                x += dx[d];                y += dy[d];                if(ck(x, y) && a[x][y] == -1){                    a[x][y] = cnt++;                    if(cnt == n * n) break;                }            }            if(cnt == n * n) break;            if(d % 2 == 1) step++;        }    }     for(int i = 1;i <= n;i++){        for(int j = 1;j <= n;j++){            cout << a[i][j] << ' ';        }        cout << '\n';    }} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);     cin >> T;    while(T--) O_o();}